Test/Demo:
```c
#include <mysql/mysql.h>
#include <stdio.h>

int main() {
  MYSQL mysql;
  mysql_init(&mysql);

  if (!mysql_real_connect(&mysql, "127.0.0.1", "root", NULL, "test", 4000, NULL,
                          0)) {
    fprintf(stderr, "Failed to connect: %s\n", mysql_error(&mysql));
  }

  MYSQL_RES *fields = mysql_list_fields(&mysql, "t1", "%");

  if (fields) {
    int field_cnt = mysql_num_fields(fields);

    for (int i = 0; i < field_cnt; ++i) {
      MYSQL_FIELD *col = mysql_fetch_field_direct(fields, i);
      printf("Column %d: name=%s, default=%s\n", i, col->name,
             col->flags & NO_DEFAULT_VALUE_FLAG ? "<no default>" : col->def);
    }
  } else {
    if (mysql_errno(&mysql)) {
      fprintf(stderr, "Failed to get field info: %s\n", mysql_error(&mysql));
    }
  }
  mysql_free_result(fields);
}
```

Makefile:
```make
CFLAGS := $(shell mysql_config --cflags --libs) -Wall -Wextra
all:
	gcc ${CFLAGS} mysql_field_default.c -o mysql_field_default
```

Table:
```sql
CREATE TABLE t1 (
  id INT PRIMARY KEY AUTO_INCREMENT,
  c1 VARCHAR(100) DEFAULT 'test',
  c2 TINYINT DEFAULT 123,
  c3 INT NOT NULL
)
```

